R=[
("संतरे और वाटरक्रेस के साथ अलास्का सैल्मन",
 "अलास्का सीफ़ूड मार्केटिंग इंस्टीट्यूट का यह स्वादिष्ट सैल्मन व्यंजन सेहतमंद वसा से भरपूर है, साथ ही इसमें कई पौष्टिक और सजावटी तत्व हैं जो इसे शानदार प्रस्तुति देते हैं। यह एक तेज़ और आसान व्यंजन है जो प्रभावित करने के लिए भी बनाया गया है!",
 "8","1/2 फ़िलेट + 1 कप टॉपिंग",
 ["4 जमे हुए अलास्का सैल्मन फ़िलेट (प्रत्येक 6 औंस)","4 बड़े चम्मच एवोकाडो का तेल (बाँटकर)","1/8 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च","2 गुच्छे (लगभग 3 कप) वाटरक्रेस (मोटे तौर पर कटा हुआ)","3 बड़े चम्मच खीरा (बारीक कटा हुआ)","2 मध्यम संतरे (छिले और फाँकों में अलग किए हुए (झिल्ली हटाई हुई))","2 कप मिली-जुली हरी पत्तियाँ","1/2 मध्यम एवोकाडो (गुठली निकाला, छिला और कटा हुआ)","1/4 कप अखरोट","2 बड़े चम्मच एप्पल साइडर सिरका","1/8 छोटा चम्मच पिमेंतोन (स्मोक्ड पेपरिका) (ऊपर से डालने के लिए)","4 खाने योग्य फूल, जैसे नैस्टर्शियम (वैकल्पिक)"],
 ["जमे हुए अलास्का सैल्मन से बर्फ़ की कोई भी परत ठंडे पानी से धो लें; पेपर टॉवल से थपथपाकर सुखाएँ। कड़ाही को मध्यम-तेज़ आँच पर गरम करें और मछली के दोनों तरफ़ 3 बड़े चम्मच एवोकाडो का तेल लगाएँ। सैल्मन को बिना ढके लगभग 4 मिनट, भूरा होने तक पकाएँ।","सैल्मन को पलटें और हल्के से 1/8 छोटा चम्मच नमक और 1/8 छोटा चम्मच काली मिर्च से मसाला लगाएँ। जमी हुई मछली के लिए 6 से 8 मिनट और, या ताज़ी/पिघलाई हुई के लिए 3 से 4 मिनट और पकाएँ, बस तब तक जब तक मछली अंदर तक अपारदर्शी न हो जाए।","इस बीच, एक मध्यम कटोरे में वाटरक्रेस, खीरा और संतरे की फाँकें मिलाएँ।","एक छोटे कटोरे में बचा हुआ एवोकाडो का तेल, एप्पल साइडर सिरका और 1/8 छोटा चम्मच नमक व काली मिर्च मिलाएँ।","सैल्मन के बगल में मिली-जुली हरी पत्तियाँ परोसें और ऊपर एवोकाडो, अखरोट और एप्पल साइडर विनेग्रेट डालें। चाहें तो नैस्टर्शियम डालें और परोसें।"]),
("फ़ेटा के साथ चुकंदर और अरुगुला सलाद",
 "क्या आपने पहले कभी चुकंदर के साथ खाना नहीं पकाया? यह तेज़ और आसान रेसिपी शुरू करने के लिए एक बढ़िया जगह है। भुना हुआ चुकंदर, अरुगुला और फ़ेटा स्वादों का एक स्वादिष्ट मेल बनाते हैं!",
 "2","1 कप (दबाकर भरा हुआ)",
 ["2 मध्यम चुकंदर (छंटे, छिले, हर एक आठ भागों में कटा हुआ)","3 छोटे चम्मच ज़ैतून का तेल (बाँटकर इस्तेमाल करें)","1/8 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच व्हाइट वाइन सिरका","1/4 छोटा चम्मच डिजॉन सरसों","1 1/2 औंस अरुगुला (दबाकर भरा हुआ लगभग 1 1/2 कप)","3 बड़े चम्मच फ़ेटा चीज़ (फैट-फ़्री, चूरा किया हुआ)"],
 ["ओवन को 400 डिग्री F पर पहले से गरम करें।","चुकंदर को किनारे वाली बेकिंग शीट पर एक परत में रखें। चुकंदर पर 1 छोटा चम्मच तेल डालें। चुकंदर पर काली मिर्च छिड़कें।","20-25 मिनट भूनें, या जब तक कांटे से जाँचने पर नरम न हो जाएँ। बेकिंग शीट पर ही 10 मिनट ठंडा होने दें।","इस बीच, एक बड़े कटोरे में बचे हुए 2 छोटे चम्मच तेल, सिरका और सरसों फेंटें। अरुगुला डालें और पत्तियों को ड्रेसिंग में घुमाएँ (इसके लिए चिमटा अच्छा काम करता है)। ठंडा किया हुआ चुकंदर डालें। फ़ेटा छिड़कें। मिलाने के लिए उछालें।","शेफ़ की सलाह: ज़्यादातर रेसिपी चुकंदर को साबुत भूनने और पकाने के बाद छीलने की सलाह देती हैं। पकाने का समय काफ़ी कम करने के लिए, इन्हें कच्चे ही छीलें (सब्ज़ी छीलने वाला अच्छा काम करता है) और भूनने से पहले चार या आठ टुकड़ों में काट लें। चुकंदर कपड़ों पर दाग़ लगा सकता है, इसलिए चुकंदर को संभालने से पहले आप एप्रन और डिस्पोज़ेबल प्लास्टिक के दस्ताने पहनना चाह सकते हैं।"]),
("क्विनोआ सीफ़ूड पाएया",
 "लेखिका और सेलिब्रिटी शेफ़ इंग्रिड हॉफ़मैन कहती हैं, \"स्पेन से माफ़ी, लेकिन मुझे पाएया का यह संस्करण मूल से ज़्यादा पसंद है; क्विनोआ स्वाद को उस चावल या अर्रोज़ बोम्बा से ज़्यादा सोखती लगती है जो क्लासिक स्पेनिश व्यंजन में इस्तेमाल होता है। मुझे लगता है कि कई लोगों को परोसते समय पाएया पेश करने के लिए इतना आसान और सुंदर व्यंजन है। एक मुख्य सामग्री केसर है। मैं फ़ारसी (ईरानी) केसर इस्तेमाल करती हूँ, जिसे मैं ऑनलाइन खरीदती हूँ, क्योंकि मुझे यह सुपरमार्केट में मिलने वाले व्यावसायिक संस्करणों से ज़्यादा पसंद है। इसमें बहुत स्वाद है, इसलिए थोड़ा ही बहुत काम करता है। मैं इसे पीसकर अपने फ़्रिज में रखती हूँ और स्ट्यू, सूप, चावल, सब्ज़ियों आदि में इस्तेमाल करती हूँ।\" यह रेसिपी स्पेनिश में पाने के लिए यहाँ क्लिक करें।",
 "8","1 कप",
 ["1 बड़ा चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","1 मध्यम प्याज़ (बारीक कटा हुआ)","1 मध्यम लाल शिमला मिर्च (पतली कटी हुई)","1 मध्यम हरी शिमला मिर्च (पतली कटी हुई)","4 लहसुन की कलियाँ (बारीक कटी हुई)","1 बड़ा चम्मच टमाटर का पेस्ट","1 छोटा चम्मच स्पेनिश केसर के धागे","1 कप बिना पकाई क्विनोआ (धोई हुई)","2 कप कम सोडियम वाला चिकन ब्रॉथ","1 (10 औंस) डिब्बा डिब्बाबंद कटे हुए टमाटर","1/4 छोटा चम्मच कोशर नमक","1 पाउंड, लगभग 30 झींगे जंगली, कभी न जमाए गए, बड़े झींगे, छिले और नस निकाली हुई","1 पाउंड कैलमारी के छल्ले","3 बड़े चम्मच चपटी पत्ती वाला अजमोद (कटा हुआ)","1 मध्यम नींबू (8 फाँकों में कटा हुआ)"],
 ["एक बड़ी नॉनस्टिक कड़ाही या पाएया पैन में मध्यम-तेज़ आँच पर तेल गरम करें। प्याज़, शिमला मिर्च और लहसुन डालें और बीच-बीच में चलाते हुए सब्ज़ियों के नरम होने तक, लगभग 8 मिनट, पकाएँ।","कड़ाही में टमाटर का पेस्ट और केसर डालें, अच्छी तरह मिलने तक चलाएँ। क्विनोआ, ब्रॉथ, टमाटर और नमक डालें; उबाल आने दें। आँच मध्यम-धीमी करें। ढककर तरल के सूखने और क्विनोआ के नरम होने तक, लगभग 20 मिनट, उबालें।","झींगे और कैलमारी को क्विनोआ के मिश्रण में दबा दें। ढककर झींगे और कैलमारी के अंदर तक पकने तक, लगभग 5 मिनट, पकाएँ। आँच से उतारें; अजमोद छिड़कें और नींबू की फाँकों से सजाएँ।"]),
("पिसे हुए अलसी के बीज",
 "पिसे हुए अलसी के बीजों की पोषण संबंधी जानकारी",
 "1","1 बड़ा चम्मच",
 ["1 बड़ा चम्मच पिसे हुए अलसी के बीज"],[]),
("बिना क्रस्ट वाला शतावरी और शिमला मिर्च मिनी क्विश",
 "इन मिनी क्विश को बेक करके ठंडा होने के बाद फ़्रीज़ किया जा सकता है। चलते-फिरते बढ़िया नाश्ते या दोपहर के खाने के लिए इन्हें टोस्टर ओवन या माइक्रोवेव में दोबारा गरम करें!",
 "12","1 मिनी क्विश",
 ["1 नॉनस्टिक कुकिंग स्प्रे","1 बड़ा चम्मच ज़ैतून का तेल","1 गुच्छा शतावरी (छंटा हुआ और छोटे टुकड़ों में कटा हुआ)","1 छोटा प्याज़ (छोटे टुकड़ों में कटा हुआ)","1 लाल या पीली शिमला मिर्च (बीज निकाली हुई और छोटे टुकड़ों में कटी हुई)","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","8 मध्यम 2 अंडे, 6 अंडों की सफ़ेदी","1/3 कप स्किम दूध","6 फाँकें Laughing Cow Light Original Cheese Wedges (आधी कटी हुई)"],
 ["ओवन को 375 डिग्री पर पहले से गरम करें।","मफ़िन पैन पर कुकिंग स्प्रे करें।","एक मध्यम सॉते पैन में ज़ैतून का तेल और भरपूर मात्रा में कुकिंग स्प्रे डालें। शतावरी, प्याज़ और शिमला मिर्च को 7-9 मिनट या अंदर तक पकने तक भूनें। नमक (वैकल्पिक) और काली मिर्च से मसाला लगाएँ और थोड़ा ठंडा होने के लिए एक तरफ़ रख दें।","एक मध्यम कटोरे में अंडे, अंडों की सफ़ेदी और दूध फेंटकर मिला लें।","भुनी हुई सब्ज़ियों को 12 मफ़िन कप में बराबर बाँटें। कप 1/2 से 3/4 भरे होने चाहिए। अंडे का मिश्रण हर मफ़िन कप की सब्ज़ियों पर धीरे से डालें, बराबर बाँटते हुए। कप भरे होने चाहिए लेकिन छलकने नहीं चाहिए।","Lite Laughing Cow Cheese Wedge का एक आधा हिस्सा लें और हर क्विश के बीच में उसे धीरे से दबाएँ। बाकी 11 क्विश के लिए दोहराएँ।","20 मिनट बेक करें। तुरंत परोसें।"]),
("चीज़ और सब्ज़ियों वाले पिटा",
 "यह शाकाहारी पिटा सैंडविच रेसिपी बहुत सारे लोगों के लिए बनाना आसान है। इसे पैक करके काम पर ले जाना भी आसान है ताकि आपको दोपहर के खाने के समय बाहर न खाना पड़े।",
 "8","1/2 पिटा",
 ["1 बड़ा टमाटर (4 बराबर टुकड़ों में कटा हुआ)","2 1/4 स्लाइस स्विस चीज़ (कम वसा वाला)","1 मध्यम लाल प्याज़ (पतला कटा हुआ)","2 बड़े चम्मच लाइट मेयोनेज़","2 कप अरुगुला","1/4 कप सूरजमुखी के बीज","4 मध्यम साबुत गेहूँ के पिटा","1/2 कप ह्यूमस","1 मध्यम खीरा"],
 ["हर पिटा के एक तरफ़ को काटकर जेब खोलें, लेकिन पूरा न काटें। एक तरफ़ रख दें।","हर पिटा में 1/2 बड़ा चम्मच मेयोनेज़ लगाएँ।","स्विस चीज़ को 4 बराबर स्लाइस में काटें। हर चीज़ स्लाइस पर 2 बड़े चम्मच ह्यूमस लगाएँ और ऊपर 1 बड़ा चम्मच सूरजमुखी के बीज छिड़कें।","ह्यूमस के ऊपर लगभग 1/2 कप अरुगुला, प्याज़ के टुकड़े, टमाटर के टुकड़े और खीरे के टुकड़ों की परतें लगाएँ।","हर पिटा में सैंडविच की भरावन भरें और आधा काट लें।"]),
("बजट के अनुकूल भुनी सब्ज़ियों वाले टैको",
 "क्या आप हफ़्ते में एक बार बिना मांस वाला, सब्ज़ियों से भरपूर भोजन खाने की कोशिश कर रहे हैं? यह रेसिपी आपको टैको का सारा स्वाद देती है, लेकिन कहीं ज़्यादा फ़ाइबर और सब्ज़ियों के साथ। चाहें तो अतिरिक्त स्वाद के लिए ऊपर एवोकाडो के टुकड़े डालें।",
 "8","1 टैको",
 ["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 मध्यम ज़ुकीनी (छोटे टुकड़ों में कटी हुई)","5 मध्यम गाजरें (छोटे टुकड़ों में कटी हुई)","1 छोटा प्याज़ (छोटे टुकड़ों में कटा हुआ)","1 मध्यम लाल शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","1 1/2 बड़े चम्मच ज़ैतून का तेल","1 लहसुन की कली (बारीक कटी हुई)","1 मध्यम टमाटर (बीज निकाला और छोटे टुकड़ों में कटा हुआ)","1 कप काली बीन्स (कम सोडियम, छानकर और धोकर)","1 बड़ा चम्मच + 1 छोटा चम्मच चिली पाउडर","1 छोटा चम्मच जीरा","1/4 छोटा चम्मच काली मिर्च","8 पूरी मक्के की टॉर्टिला (6 इंच)","1 कप सलाद पत्ता (बारीक कटा हुआ)","1/2 कप केसो फ़्रेस्को ((या कम वसा वाला कसा हुआ चेडर))"],
 ["ओवन को 400 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे करें।","ज़ुकीनी, गाजर, प्याज़ और लाल शिमला मिर्च को बेकिंग शीट पर रखें। ज़ैतून का तेल और लहसुन डालें; लपेटने के लिए मिलाएँ। 15-18 मिनट बेक करें। ओवन से निकालें।","जब सब्ज़ियाँ बेक हो रही हों, तब एक मध्यम सॉते पैन को मध्यम आँच पर गरम करें। उस पर कुकिंग स्प्रे करें। टमाटर डालें और 1 मिनट भूनें। बीन्स, चिली पाउडर, जीरा और काली मिर्च डालें और 2 मिनट भूनें। पकी हुई सब्ज़ियाँ पैन में डालें और अच्छी तरह मिलाएँ।","हर टैको में 1/2 कप सब्ज़ी का मिश्रण परोसें और ऊपर सलाद पत्ता और चीज़ डालें।"]),
("बेक्ड दालचीनी भरे सेब",
 "इन बेक्ड दालचीनी भरे सेबों जैसे फलों के व्यंजन एक शानदार, सेहतमंद मिठाई बन सकते हैं। ओवन में बेक होते इन सेबों की खुशबू आपके मुँह में पानी ला देगी।",
 "8","1/2 सेब",
 ["4 बड़े सेब (मैकिंटोश या गोल्डन डिलिशियस सेब, बीच का हिस्सा निकाला हुआ)","1/2 नींबू (रस निकाला हुआ)","6 बड़े चम्मच कम कैलोरी वाला ब्राउन शुगर का विकल्प","1/4 कप ओटमील","1 छोटा चम्मच पिसी दालचीनी","2 बड़े चम्मच मार्जरीन (ट्रांस-फ़ैट-फ़्री)","1/4 कप पेकन (बारीक कटे हुए)"],
 ["ओवन को 425 डिग्री पर पहले से गरम करें।","सेबों पर नींबू का रस डालें।","एक छोटे कटोरे में बाकी सामग्री मिलाएँ। हर सेब में लगभग 1/4 कप ओट का मिश्रण भरें।","सेबों को ओवन-सुरक्षित बेकिंग डिश में रखें और 25-30 मिनट बेक करें।"]),
("सब्ज़ियों वाले सूफ़्ले एग मफ़िन",
 "हल्के और फूले हुए, ये छोटे नाश्ते वाले मफ़िन स्वाद से भरपूर हैं। ये बड़े जमावड़े के लिए एकदम सही हैं या चलते-फिरते जल्दी नाश्ते के लिए फ़्रीज़ करके दोबारा गरम किए जा सकते हैं।",
 "6","3 मफ़िन",
 ["6 बड़े अंडे (अलग किए हुए)","1/2 कप कम वसा वाला कॉटेज चीज़","1/2 कप गाजर (छोटे टुकड़ों में कटी हुई)","1/2 कप ब्रोकली के छोटे फूल","1/2 कप ताज़ा केल (कटी हुई)","1/2 कप लाल शिमला मिर्च (छोटी, छोटे टुकड़ों में कटी हुई)","1/4 कप प्याज़ (छोटे, छोटे टुकड़ों में कटा हुआ)","1/2 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच कोशर नमक"],
 ["ओवन को 350°F पर पहले से गरम करें। 12 कप वाले 2 मफ़िन टिन पर कुकिंग स्प्रे करें।","अंडे की सफ़ेदी को अंडे की ज़र्दी से अलग करें।","एक बड़े कटोरे में अंडे की ज़र्दी और कॉटेज चीज़ को हैंड या स्टैंड मिक्सर से मध्यम-तेज़ गति पर मलाईदार होने तक फेंटें।","दूसरे बड़े कटोरे में अंडे की सफ़ेदी को कड़े शिखर बनने तक फेंटें।","सब्ज़ियों और मसालों को अंडे की ज़र्दी के मिश्रण में मिलाएँ और अच्छी तरह मिला लें।","अंडे की सफ़ेदी को अंडे की ज़र्दी और सब्ज़ियों के मिश्रण में धीरे से मिलाएँ।","स्कूप या बड़े चम्मच से अंडे के मिश्रण को 18 मफ़िन कप में बराबर बाँटें।","टिन को पहले से गरम किए ओवन में रखें और 25-30 मिनट बेक करें, जब तक कि ऊपर से फूल न जाएँ और भूरे न हो जाएँ।","ओवन से निकालें और 5 मिनट ठंडा होने दें। मफ़िन को टिन से धीरे से निकालें।"]),
("चटपटी सरसों की सॉस के साथ ब्लैकन्ड टूना",
 "यह व्यंजन स्टोव पर सॉते पैन में भी बहुत अच्छा बनता है।",
 "4","1 टूना फ़िलेट",
 ["1/2 छोटा चम्मच लाल मिर्च पाउडर (केयेन) (वैकल्पिक)","1 छोटा चम्मच सूखा थाइम (सूखा)","1 छोटा चम्मच सूखा अजवायन (ओरिगैनो) (सूखा)","1 बड़ा चम्मच पेपरिका","1 छोटा चम्मच चिली पाउडर","1 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच नमक (वैकल्पिक)","1 पाउंड अही टूना फ़िलेट (4 भागों में बँटा, 4 औंस के फ़िलेट)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 बड़े चम्मच सादा बिना वसा वाला ग्रीक योगर्ट","1 बड़ा चम्मच डिजॉन सरसों","1 छोटा चम्मच कम सोडियम वाला सोया सॉस","1 बड़ा चम्मच ताज़ा अजमोद (कटा हुआ)"],
 ["इनडोर या आउटडोर ग्रिल तैयार करें।","पेपरिका, चिली पाउडर, अजवायन, थाइम, लाल मिर्च पाउडर (वैकल्पिक), पिसी काली मिर्च, लहसुन पाउडर और नमक (वैकल्पिक) मिलाएँ।","हर टूना फ़िलेट के दोनों तरफ़ ब्लैकनिंग मसाला अच्छी तरह मलें।","टूना फ़िलेट पर कुकिंग स्प्रे करें और हर तरफ़ 4-5 मिनट ग्रिल करें। टूना बीच में हल्का गुलाबी होना चाहिए।","एक छोटे कटोरे में दही, सरसों और सोया सॉस फेंटकर मिला लें। सॉस को 4 टूना फ़िलेट में बराबर बाँटें और परोसने से ठीक पहले ऊपर डालें और कटा हुआ ताज़ा अजमोद छिड़कें।"]),
("सेब के साथ गाजर का सलाद",
 "चलिए कुरकुरे हो जाएँ! इस साइड सलाद में सेब और गाजर खूबसूरती से मिलते हैं, जिन पर खट्टा सिरका, सरसों से थोड़ी तीखापन और मेपल सिरप से बस थोड़ी-सी प्राकृतिक मिठास डाली गई है।",
 "4","1 कप",
 ["4 बड़ी गाजरें (छिली और कद्दूकस की हुई)","1 मध्यम सेब (बीच का हिस्सा निकाला और छोटे टुकड़ों में कटा हुआ)","3 बड़े चम्मच ज़ैतून का तेल","2 बड़े चम्मच एप्पल साइडर सिरका","1 छोटा चम्मच डिजॉन सरसों","1 बड़ा चम्मच बिना मीठा बहु-उपयोगी सिरप","1/4 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच ताज़ा अजमोद (कटा हुआ, सजावट के लिए)"],
 ["एक बड़े कटोरे में कद्दूकस की हुई गाजर और कटे हुए सेब को मिलाएँ।","एक अलग, छोटे कटोरे में ज़ैतून का तेल, एप्पल साइडर सिरका, डिजॉन सरसों, सिरप, नमक और काली मिर्च फेंटकर मिला लें।","ड्रेसिंग को गाजर और सेब के मिश्रण पर डालें।","बराबर लपेटने के लिए सलाद को धीरे से उछालकर मिलाएँ।","ठंडा या कमरे के तापमान पर परोसें।"]),
("शानदार चिकन बर्गर",
 "बारबरा सीलिग-ब्राउन ने ये बर्गर पड़ोस की एक पिकनिक के लिए बनाए थे। वह यह पक्का करना चाहती थीं कि वे ऐसी चीज़ ले जाएँ जो स्वादिष्ट होने के साथ-साथ सेहतमंद भी हो।",
 "4","1 बर्गर",
 ["1/2 पाउंड कीमा चिकन ब्रेस्ट","1/2 पाउंड कीमा चिकन (हल्का और गहरा मांस मिला हुआ)","1/4 कप सूखे टमाटर (कटे हुए, तेल में नहीं)","1/4 कप प्याज़ (कटा हुआ)","1/4 कप ताज़ी तुलसी (कटी हुई)","1/4 कप ताज़ा चपटी पत्ती वाला इटैलियन अजमोद (कटा हुआ)","4 लहसुन की कलियाँ (बारीक कटी हुई)","1/2 छोटा चम्मच बारीक समुद्री नमक","1/2 छोटा चम्मच काली मिर्च (ताज़ी कुटी हुई)"],
 ["सारी सामग्री को एक साथ मिलाएँ और 4 पैटी बनाएँ।","हर तरफ़ 3-4 मिनट ग्रिल करें और गुआकामोले के साथ परोसें।"]),
("अजवायन और फ़ेटा के साथ भुनी सब्ज़ियाँ",
 "एक मुँह में पानी लाने वाला मिश्रण आज़माएँ जो एकदम सही भुनी सब्ज़ियों के दमदार स्वादों को फ़ेटा चीज़ के नमकीन स्वाद के साथ मिलाता है, और एक पोषक तत्वों से भरपूर, भूमध्यसागरीय प्रेरणा वाला व्यंजन बनाता है जिसका आनंद पूरा परिवार लेगा।",
 "4","3/4 कप",
 ["3 कप जमी हुई मिली-जुली सब्ज़ियाँ (शतावरी, शिमला मिर्च, ज़ुकीनी, चेरी टमाटर, कटी हुई)","2 बड़े चम्मच ज़ैतून का तेल","1/2 छोटा चम्मच सूखा अजवायन (ओरिगैनो)","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच फ़ेटा चीज़"],
 ["अपने ओवन को 400 डिग्री F पर पहले से गरम करें और शीट पैन पर पार्चमेंट पेपर बिछाएँ।","मिली-जुली सब्ज़ियों को ज़ैतून के तेल, सूखे अजवायन, नमक और काली मिर्च के साथ मिलाएँ।","नरम और हल्का जला-सा होने तक 20-25 मिनट भूनें।","फ़ेटा के ऊपर परोसें।"]),
("पालक पेस्टो चिकन सलाद रैप",
 "सोडियम का सेवन देखकर अपना रक्तचाप कम करने की कोशिश कर रहे हैं? बहुत सारे स्वाद के लिए तुलसी जैसी जड़ी-बूटियाँ और नींबू, लहसुन और काली मिर्च जैसी तेज़ सामग्री का इस्तेमाल करें। यह रैप पालक के साथ और ज़्यादा सब्ज़ियाँ शामिल करने का भी बढ़िया तरीका है।",
 "5","1 रैप",
 ["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट","1/2 छोटा चम्मच काली मिर्च (बाँटकर इस्तेमाल करें)","1 छोटा चम्मच तुलसी (सूखी)","3 कप बेबी पालक (बड़े डंठल हटाए हुए)","2 बड़े चम्मच चिलगोज़े (भुने हुए)","2 बड़े चम्मच ताज़ा नींबू का रस","1/4 कप लाइट मेयोनेज़","1 बड़ा चम्मच ज़ैतून का तेल","2 बड़े चम्मच पारमेसन चीज़ (ताज़ा कसा हुआ)","1/4 छोटा चम्मच लहसुन पाउडर","5 छोटी 6 इंच की मक्के की टॉर्टिला"],
 ["ओवन को 350 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे करें।","चिकन ब्रेस्ट पर 1/4 छोटा चम्मच काली मिर्च और सूखी तुलसी का मसाला लगाएँ। 35 मिनट या पकने तक बेक करें। चिकन ब्रेस्ट को ठंडा होने के लिए फ़्रिज में रखें।","फ़ूड प्रोसेसर में पालक, चिलगोज़े, नींबू का रस और मेयोनेज़ मिलाएँ। हल्के से पल्स करें। मशीन चलते हुए, ज़ैतून का तेल डालें और मिश्रण के मलाईदार होने तक ब्लेंड करें। पारमेसन चीज़, लहसुन पाउडर और 1/4 छोटा चम्मच काली मिर्च मिलाएँ।","पके हुए चिकन को 1/2 इंच के टुकड़ों में काटें और रेशे करें। एक मध्यम कटोरे में चिकन और पेस्टो सॉस मिलाएँ; अच्छी तरह मिलाएँ।","हर टॉर्टिला में 1/2 कप चिकन सलाद परोसें। टॉर्टिला के दोनों किनारे अंदर मोड़ें और बरिटो की तरह लपेटें। आप इन्हें तुरंत परोस सकते हैं या प्लास्टिक रैप में कसकर लपेटकर फ़्रिज में रख सकते हैं।"]),
("नाशपाती और कॉटेज चीज़ टोस्ट",
 "यह सरल टोस्ट मलाईदार दालचीनी-मसालेदार कॉटेज चीज़ को मीठे नाशपाती के टुकड़ों और कुरकुरे अखरोट के साथ परतों में लगाता है, जिससे एक संतोषजनक शाकाहारी और कम वसा वाला नाश्ता या स्नैक बनता है। साबुत गेहूँ की ब्रेड और ताज़ा फल फ़ाइबर जोड़ते हैं, जबकि कॉटेज चीज़ प्रोटीन जोड़ता है जो रक्त ग्लूकोज़ (ब्लड शुगर) के स्तर को नियंत्रित करने में मदद करता है। यह मधुमेह के अनुकूल एक तेज़ विकल्प है जो हर निवाले में स्वाद और पोषण का संतुलन बनाता है।",
 "4","1 स्लाइस टोस्ट 1/4 कप कॉटेज चीज़ के साथ",
 ["4 स्लाइस साबुत गेहूँ की ब्रेड (टोस्ट की हुई)","1 कप कॉटेज चीज़ (कम वसा वाला)","2 पूरी नाशपाती (पकी हुई, पतली कटी हुई)","4 छोटे चम्मच अखरोट (कटे हुए)","1/2 छोटा चम्मच पिसी दालचीनी"],
 ["साबुत गेहूँ की ब्रेड के स्लाइस को सुनहरा और कुरकुरा होने तक टोस्ट करें। थोड़ा ठंडा होने के लिए एक तरफ़ रख दें।","एक छोटे कटोरे में कम वसा वाले कॉटेज चीज़ को पिसी दालचीनी के साथ बराबर मिलने तक चलाएँ।","दालचीनी वाले कॉटेज चीज़ के मिश्रण को हर टोस्ट स्लाइस पर बराबर फैलाएँ। ऊपर कटी हुई नाशपाती और थोड़े कटे हुए अखरोट छिड़कें।"]),
]
